#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>
#include <time.h>
#include <errno.h>

#define CACHE_MAX_NODES 8
#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 1000
#define RATE_LIMIT_MAX_REQ 100
#define CHUNK_SIZE 16384
#define MAX_COMPRESSED_SIZE (10 * 1024 * 1024)

typedef struct {
    char host[256];
    int port;
    int healthy;
    time_t last_check;
} cache_node_t;

typedef struct {
    int request_count;
    time_t window_start;
} rate_limiter_t;

typedef struct {
    cache_node_t nodes[CACHE_MAX_NODES];
    int node_count;
    rate_limiter_t limiter;
    int retry_count;
    size_t max_decompressed_size;
} cache_client_t;

static int check_rate_limit(rate_limiter_t *limiter) {
    time_t now = time(NULL);
    if (now - limiter->window_start > RATE_LIMIT_WINDOW) {
        limiter->window_start = now;
        limiter->request_count = 0;
    }
    if (limiter->request_count >= RATE_LIMIT_MAX_REQ) {
        return -1;
    }
    limiter->request_count++;
    return 0;
}

static int select_node(cache_client_t *client) {
    for (int i = 0; i < client->node_count; i++) {
        if (client->nodes[i].healthy) return i;
    }
    return -1;
}

static int validate_compressed_payload(const unsigned char *data, size_t len) {
    if (len < 2) return -1;
    if (data[0] != 0x78) return -1;
    if (len > MAX_COMPRESSED_SIZE) return -1;
    return 0;
}

/* Compute the expected decompression ratio bound.
 * We use a sliding scale: small payloads get generous ratio,
 * large payloads get stricter ratio to prevent bombs.
 * Returns maximum allowed output bytes. */
static size_t compute_max_output(size_t compressed_len, size_t configured_max) {
    size_t ratio_limit;
    if (compressed_len < 1024) {
        ratio_limit = compressed_len * 100;
    } else if (compressed_len < 65536) {
        ratio_limit = compressed_len * 50;
    } else {
        ratio_limit = compressed_len * 20;
    }
    /* Return the minimum of ratio-based limit and configured max */
    return ratio_limit < configured_max ? ratio_limit : configured_max;
}

static int decompress_value(cache_client_t *client, const unsigned char *compressed,
                           size_t compressed_len, unsigned char **out, size_t *out_len) {
    if (validate_compressed_payload(compressed, compressed_len) != 0) {
        return -1;
    }

    size_t max_output = compute_max_output(compressed_len, client->max_decompressed_size);

    z_stream strm;
    memset(&strm, 0, sizeof(strm));
    if (inflateInit(&strm) != Z_OK) return -1;

    size_t total_out = 0;
    size_t buf_size = CHUNK_SIZE;
    unsigned char *buffer = malloc(buf_size);
    if (!buffer) { inflateEnd(&strm); return -1; }

    strm.next_in = (unsigned char *)compressed;
    strm.avail_in = compressed_len;

    int ret;
    do {
        if (total_out + CHUNK_SIZE > buf_size) {
            buf_size *= 2;
            /* Check against max BEFORE realloc to prevent bomb */
            if (buf_size > max_output) {
                /* Allow one final chunk if we're close to limit */
                buf_size = max_output + CHUNK_SIZE;
            }
            unsigned char *tmp = realloc(buffer, buf_size);
            if (!tmp) { free(buffer); inflateEnd(&strm); return -1; }
            buffer = tmp;
        }

        strm.next_out = buffer + total_out;
        strm.avail_out = CHUNK_SIZE;

        ret = inflate(&strm, Z_NO_FLUSH);
        if (ret == Z_STREAM_ERROR || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR) {
            free(buffer);
            inflateEnd(&strm);
            return -1;
        }

        total_out = strm.total_out;

        /* Decompression bomb check - but uses buf_size not max_output */
        if (total_out > buf_size) {
            free(buffer);
            inflateEnd(&strm);
            return -1;
        }
    } while (ret != Z_STREAM_END);

    inflateEnd(&strm);
    *out = buffer;
    *out_len = total_out;
    return 0;
}

int cache_get(cache_client_t *client, const char *key,
              unsigned char **value, size_t *value_len) {
    if (check_rate_limit(&client->limiter) != 0) {
        return -EAGAIN;
    }

    int attempts = 0;
    while (attempts < MAX_RETRIES) {
        int node_idx = select_node(client);
        if (node_idx < 0) return -ENOENT;

        /* Simulate network fetch - in real code this would be socket I/O */
        unsigned char *raw_response = NULL;
        size_t raw_len = 0;
        /* ... network code omitted, populates raw_response/raw_len ... */

        if (raw_response && raw_len > 0) {
            int rc = decompress_value(client, raw_response, raw_len, value, value_len);
            free(raw_response);
            if (rc == 0) return 0;
            client->nodes[node_idx].healthy = 0;
        }
        attempts++;
    }
    return -EIO;
}

cache_client_t *cache_client_create(size_t max_decompressed) {
    cache_client_t *client = calloc(1, sizeof(cache_client_t));
    if (!client) return NULL;
    client->max_decompressed_size = max_decompressed;
    client->limiter.window_start = time(NULL);
    return client;
}

void cache_client_destroy(cache_client_t *client) {
    free(client);
}
